import SuccessPopup from '@/components/Popups/SuccessPopup';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import CancelPopup from '@/components/Popups/CancelPopup';
import { useNavigate } from 'react-router-dom';
import { shiftInfo } from '../../types/shift.types';

interface Props {
    shift?: shiftInfo | null;
    showSuccessPopup: boolean;
    setShowSuccessPopup: (value: boolean) => void;
    showCancelPopup: boolean;
    setShowCancelPopup: (value: boolean) => void;
    loading: boolean;
}
export default function Submission({
    shift,
    setShowCancelPopup,
    setShowSuccessPopup,
    showCancelPopup,
    showSuccessPopup,
    loading,
}: Props) {
    const navigate = useNavigate();

    const handleAddAnother = () => {
        setShowSuccessPopup(false);
    };
    return (
        <>
            <div className="flex flex-row justify-end items-center mt-8">
                {shift ? (
                    <SecondaryButton
                        type="button"
                        className="xl:px-[87px] xl:py-3 text-[#A21515] border border-red-error-50 xl:font-semibold bg-red-error-50"
                        onClick={() => setShowCancelPopup(true)}
                    >
                        إلغاء الوردية
                    </SecondaryButton>
                ) : (
                    <SecondaryButton
                        type="button"
                        className="xl:px-[87px] bg-red-error-50 text-[#A21515] hover:bg-red-error-600 hover:text-white-blue-50 xl:py-3 border bordr-[#E8EFF6] xl:font-semibold"
                        onClick={() => setShowCancelPopup(true)}
                    >
                        الغاء
                    </SecondaryButton>
                )}
                <div>
                    {shift ? (
                        <PrimaryButton className="xl:px-[91px] xl:py-3 xl:font-semibold ms-6" disabled={loading}>
                            {loading ? 'جاري التحميل...' : 'حفظ التغييرات'}
                        </PrimaryButton>
                    ) : (
                        <PrimaryButton className="xl:px-[91px] xl:py-3 xl:font-semibold ms-6" disabled={loading}>
                            {loading ? 'جاري التحميل...' : 'اضافة'}
                        </PrimaryButton>
                    )}
                </div>
            </div>
            <CancelPopup
                open={showCancelPopup}
                onClickButton1={() => {
                    setShowCancelPopup(false);
                }}
                onClickButton2={() => {
                    navigate('/human-resources/shifts');
                    setShowCancelPopup(false);
                }}
                text1={shift ? 'إلغاء تعديل بيانات الوردية' : 'إلغاء إضافة وردية'}
                text2={
                    shift
                        ? 'أنت على وشك إلغاء عملية تعديل بيانات الوردية دون إكمال البيانات المطلوبة. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟'
                        : 'أنت على وشك إلغاء عملية إضافة وردية جديدة دون إكمال البيانات المطلوبة. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟'
                }
                textButton1={shift ? 'إكمال التعديل' : 'إكمال الإضافة'}
                textButton2={shift ? 'إلغاء التعديل' : 'إلغاء الإضافة'}
            />
            <SuccessPopup
                text1={shift ? 'تم تعديل بيانات الوردية بنحاح' : 'تم إضافة وردية جديدة بنحاح'}
                text2={shift ? 'تم تعديل بيانات الوردية بنحاح' : 'تم تسجيل بيانات الوردية الجديدة بنجاح.'}
                textButton1="العودة لقائمة الورديات"
                textButton2={shift ? 'تعديل بيانات اخرى' : 'إضافة وردية أخرى'}
                open={showSuccessPopup}
                onAddAnother={handleAddAnother}
                onReturnToList={() => {
                    navigate('/human-resources/shifts');
                    setShowSuccessPopup(false);
                }}
            />
        </>
    );
}
